import { action } from '@mezielabs/azu'
import type Product from '#models/product'

/**
 * Feature: a bulk action. Add it to a resource's `actions`;
 * tsc checks that the resource's policy has a `feature` method,
 * which Azu calls with the user and each record.
 *
 * Generated by `node ace make:admin-action Feature --bulk`, then given
 * its records' type and its change.
 */
export default action
  .bulk('feature')
  .confirm('Feature the selected products on the storefront?')
  .ability('feature')
  .handle(async (products: Product[], { trx }) => {
    for (const product of products) {
      // The handler runs in a transaction: run every query through `trx`
      // (`Model.query({ client: trx })`), so a thrown error rolls back
      // everything the action did.
      product.isFeatured = true
      await product.useTransaction(trx).save()
    }
    return {
      message: `Featured ${products.length} ${products.length === 1 ? 'product' : 'products'}`,
    }
  })
